// Mint a REAL Supabase session for the throwaway test user and hand it to a
// browser context as the exact cookies @supabase/ssr writes — generated by the
// app's own @supabase/ssr module so the encoding cannot drift.
const fs = require("fs");
const path = require("path");
const { chromium } = require("playwright");
const { createServerClient } = require("@supabase/ssr");

const ENVF = "C:/Users/hamis/projects/_hdd-data/env/supabase.env";
const STATE = path.join(__dirname, "testuser-state.json");

function readEnv() {
  const env = {};
  for (const line of fs.readFileSync(ENVF, "utf8").split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
    if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
  return env;
}

async function sessionFor(email) {
  const env = readEnv();
  const url = env.NEXT_PUBLIC_SUPABASE_URL;
  const anon = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  const srk = env.SUPABASE_SERVICE_ROLE_KEY;
  const h = { apikey: srk, Authorization: `Bearer ${srk}`, "Content-Type": "application/json" };

  const gl = await fetch(`${url}/auth/v1/admin/generate_link`, {
    method: "POST", headers: h,
    body: JSON.stringify({ type: "magiclink", email, redirect_to: "https://sumaiya.app/auth/callback" }),
  });
  const gj = await gl.json();
  if (!gj.action_link) throw new Error("no action_link: " + JSON.stringify(gj).slice(0, 200));

  // The magic-link flow hands the session back in the redirect FRAGMENT
  // (#access_token=…&refresh_token=…). Read it off the Location header so the
  // token is never consumed by a browser.
  const vr = await fetch(gj.action_link, { redirect: "manual" });
  const loc = vr.headers.get("location") || vr.headers.get("Location") || "";
  const frag = loc.includes("#") ? loc.split("#")[1] : "";
  const q = new URLSearchParams(frag);
  const access_token = q.get("access_token");
  const refresh_token = q.get("refresh_token");
  if (!access_token || !refresh_token) {
    throw new Error(`no session in redirect (status ${vr.status}, loc=${loc.slice(0, 160)})`);
  }
  return {
    session: { access_token, refresh_token, expires_in: Number(q.get("expires_in") || 3600) },
    url, anon, srk,
  };
}

/** Use the app's own ssr package to encode the session into Set-Cookie values. */
async function cookiesFor(session, url, anon) {
  const jar = new Map();
  const client = createServerClient(url, anon, {
    cookies: {
      getAll: () => [...jar.entries()].map(([name, value]) => ({ name, value })),
      setAll: (list) => list.forEach(({ name, value }) => jar.set(name, value)),
    },
  });
  const { error } = await client.auth.setSession({
    access_token: session.access_token,
    refresh_token: session.refresh_token,
  });
  if (error) throw new Error("setSession: " + error.message);
  return [...jar.entries()].map(([name, value]) => ({
    name, value,
    domain: "sumaiya.app", path: "/", httpOnly: false, secure: true, sameSite: "Lax",
  }));
}

(async () => {
  const email = process.argv[2] || "qa-io-matrix-1@sumaiya-seam.invalid";
  const { session, url, anon } = await sessionFor(email);
  const cookies = await cookiesFor(session, url, anon);
  console.log("session user:", session.user?.email, "expires_in:", session.expires_in);
  console.log("cookies:", cookies.map((c) => `${c.name}(${c.value.length}B)`).join(", "));

  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  await ctx.addCookies(cookies);
  const page = await ctx.newPage();
  await page.goto("https://sumaiya.app/dashboard?lang=en", { waitUntil: "domcontentloaded", timeout: 60000 });
  await page.waitForTimeout(6000);
  const finalUrl = page.url();
  const body = (await page.innerText("body")).slice(0, 400);
  console.log("dashboard url:", finalUrl);
  console.log("body head:", JSON.stringify(body));
  await ctx.storageState({ path: STATE });
  console.log("saved:", STATE);
  await browser.close();
})().catch((e) => { console.error("FATAL", String(e).slice(0, 400)); process.exit(1); });
